    FROM public.title_odds;

CREATE OR REPLACE VIEW ask.track_status_events AS
  SELECT session_id,
         event_idx,
         session_time_s,
         status,
         message
    FROM public.track_status_events;

CREATE OR REPLACE VIEW ask.weather_samples AS
  SELECT session_id,
         sample_idx,
         session_time_s,
         air_temp,
         humidity,
         pressure,
         rainfall,
         track_temp,
         wind_direction,
         wind_speed
    FROM public.weather_samples;

CREATE OR REPLACE VIEW ask.wp_lap_probability AS
  SELECT session_id,
         assumption_set_id,
         driver_id,
         lap_number,
         pred_kind,
         fold_index,
         p_win_raw,
         p_win,
         degraded
    FROM public.wp_lap_probability;

CREATE OR REPLACE VIEW ask.wp_metrics AS
  SELECT assumption_set_id,
         scope,
         variant,
         n_rows,
         n_races,
         brier,
         log_loss,
         brier_baseline_pos,
         brier_baseline_lead,
         brier_fold_min,
         brier_fold_median,
         brier_fold_max,
         note
    FROM public.wp_metrics;

CREATE OR REPLACE VIEW ask.wp_reliability_bin AS
  SELECT assumption_set_id,
         scope,
         variant,
         bin_index,
         bin_lo,
         bin_hi,
         n_rows,
         n_wins,
         mean_predicted,
         observed_rate,
         observed_lo,
         observed_hi
    FROM public.wp_reliability_bin;

CREATE OR REPLACE VIEW ask.wp_swing AS
  SELECT session_id,
         assumption_set_id,
         lap_number,
         swing_mass,
         cause,
         mover_driver_id,
         mover_p_before,
         mover_p_after,
         rank_in_race
    FROM public.wp_swing;

-- 4 curated views

CREATE OR REPLACE VIEW ask.session_health AS
  SELECT si.session_id, s.year, s.round, s.kind, s.name, si.status, si.analytics_status,
         si.raw_laps, si.clean_laps, si.total_laps,
         coalesce(array_length(si.warnings, 1), 0) AS warning_count
    FROM public.session_ingests si
    JOIN public.sessions s USING (session_id);

CREATE OR REPLACE VIEW ask.data_coverage AS
  SELECT year,
         count(*) FILTER (WHERE status = 'ok')      AS sessions_ok,
         count(*) FILTER (WHERE status = 'partial') AS sessions_partial,
         min(round) AS first_round,
         max(round) AS last_round
    FROM ask.session_health
   GROUP BY year;

CREATE OR REPLACE VIEW ask.race_index AS
  SELECT s.session_id, s.year, s.round, s.kind, s.name AS session_name,
         e.event_name, e.location, e.country,
         c.short_name AS circuit_short_name, c.circuit_key
    FROM public.sessions s
    JOIN public.events e USING (year, round)
    JOIN public.circuits c USING (circuit_key);

CREATE OR REPLACE VIEW ask.driver_index AS
  SELECT d.driver_id, d.latest_code, d.full_name, d.first_name, d.last_name, d.country_code
    FROM public.drivers d;

-- The allowlist IS the grant: 65 objects, named one by one.

DO $ask_grant$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'f1_ask') THEN
    EXECUTE $g$GRANT USAGE ON SCHEMA ask TO f1_ask$g$;
    EXECUTE $g$GRANT SELECT ON
           ask.assumption_sets,
           ask.circuit_corners,
           ask.circuit_odi,
           ask.circuits,
           ask.compound_colours,
           ask.compound_degradation,
           ask.constructor_standings,
           ask.degradation_fits,
           ask.driver_season_summary,
           ask.driver_standings,
           ask.drivers,
           ask.events,
           ask.fuel_sensitivity,
           ask.lap_corner_speeds,
           ask.lap_status,
           ask.lap_telemetry_summary,
           ask.laps,
           ask.mode2_car_hazard,
           ask.mode2_car_rating,
           ask.mode2_career_season,
           ask.mode2_component,
           ask.mode2_counterfactual,
           ask.mode2_driver_contrast,
           ask.mode2_driver_rating,
           ask.mode2_driver_rating_history,
           ask.mode2_driver_skill,
           ask.mode2_points_calib,
           ask.mode2_quali_row_audit,
           ask.optimal_stint,
           ask.pace_ranking,
           ask.pit_stops,
           ask.preview_backtest,
           ask.preview_finish_order,
           ask.preview_round,
           ask.quali_results,
           ask.quali_segment_times,
           ask.quali_teammate_h2h,
           ask.race_moment,
           ask.results,
           ask.season_quali_h2h,
           ask.seasons,
           ask.session_entries,
           ask.session_teams,
           ask.sessions,
           ask.sim_circuit_hazard,
           ask.sim_compound_params,
           ask.sim_driver_compound,
           ask.sim_driver_params,
           ask.sim_race_params,
           ask.stints,
           ask.teammate_deltas,
           ask.teammate_h2h,
           ask.teams,
           ask.title_clinch,
           ask.title_odds,
           ask.track_status_events,
           ask.weather_samples,
           ask.wp_lap_probability,
           ask.wp_metrics,
           ask.wp_reliability_bin,
           ask.wp_swing,
           ask.session_health,
           ask.data_coverage,
           ask.race_index,
           ask.driver_index
      TO f1_ask$g$;
  ELSE
    RAISE NOTICE 'role f1_ask does not exist yet - run scripts/sql/0005_roles.sql, then re-run this file so the enumerated GRANT is applied';
  END IF;
END
$ask_grant$;

COMMIT;
